
from __future__ import annotations

import ast
import base64
import os
import re
import shutil
import time
from pathlib import Path

ROOT = Path(r"C:\Users\walim\RedSight")
COMMAND_CENTER = ROOT / "app" / "ui" / "command_center.py"
LAUNCHER = ROOT / "launch_redsight_command_center.py"
GATEWAY10 = ROOT / "redsight_actions" / "gateway_stage10.py"
PALETTE10 = ROOT / "app" / "ui" / "action_palette_stage10.py"

STAMP = time.strftime("%Y%m%d-%H%M%S")
BACKUP = ROOT / ".repair-backups" / ("stage10-source-" + STAMP)
BACKUP.mkdir(parents=True, exist_ok=True)

GATEWAY_SOURCE = base64.b64decode("").decode("utf-8")
PALETTE_SOURCE = base64.b64decode("").decode("utf-8")
HELPER_SOURCE = base64.b64decode("").decode("utf-8")


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig", errors="replace")


def atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".stage10.tmp")
    temp.write_text(text, encoding="utf-8")
    os.replace(temp, path)


def backup(path: Path) -> None:
    if path.exists():
        shutil.copy2(path, BACKUP / (path.name + ".before"))


for required in (
    COMMAND_CENTER,
    LAUNCHER,
    ROOT / "redsight_actions" / "gateway_stage91.py",
    ROOT / "app" / "ui" / "action_palette_stage91.py",
):
    if not required.exists():
        raise RuntimeError("Missing required Stage 9.1 component: " + str(required))

for path in (COMMAND_CENTER, LAUNCHER, GATEWAY10, PALETTE10):
    backup(path)

ast.parse(GATEWAY_SOURCE, filename=str(GATEWAY10))
ast.parse(PALETTE_SOURCE, filename=str(PALETTE10))

command_source = read(COMMAND_CENTER)

begin = "# REDSIGHT_STAGE10_CONTEXT_BEGIN"
end = "# REDSIGHT_STAGE10_CONTEXT_END"

command_source = re.sub(
    re.escape(begin) + r".*?" + re.escape(end) + r"\s*",
    "",
    command_source,
    flags=re.S,
)

class_match = re.search(
    r"(?m)^class\s+CommandCenterMainWindow\b",
    command_source,
)
if not class_match:
    raise RuntimeError("CommandCenterMainWindow class not found.")

command_source = (
    command_source[:class_match.start()]
    + HELPER_SOURCE.strip()
    + "\n\n"
    + command_source[class_match.start():]
)

method_match = re.search(
    (
        r"(?ms)"
        r"^    async def _send_to_api\s*\("
        r".*?"
        r"(?=^    (?:async def|def)\s+\w+\s*\(|\Z)"
    ),
    command_source,
)
if not method_match:
    raise RuntimeError("_send_to_api method not found.")

method = method_match.group(0)

if "_redsight_stage10_messages(message)" not in method:
    if "_redsight_heritage_messages(message)" in method:
        method = method.replace(
            "_redsight_heritage_messages(message)",
            "_redsight_stage10_messages(message)",
            1,
        )
    else:
        method_new, count = re.subn(
            (
                r'json\s*=\s*\{'
                r'\s*"messages"\s*:\s*\['
                r'\s*\{\s*"role"\s*:\s*"user"\s*,'
                r'\s*"content"\s*:\s*message\s*\}'
                r'\s*\]\s*,'
                r'\s*"stream"\s*:\s*False\s*'
                r'\}'
            ),
            'json={"messages": _redsight_stage10_messages(message), "stream": False}',
            method,
            count=1,
            flags=re.S,
        )
        if count == 0:
            raise RuntimeError(
                "Could not locate current chat messages payload in _send_to_api."
            )
        method = method_new

if "_redsight_stage10_commit(data)" not in method:
    lines = method.splitlines()
    inserted = False
    output = []
    for line in lines:
        output.append(line)
        if (
            not inserted
            and re.match(
                r"^\s*data\s*=\s*[A-Za-z_][A-Za-z0-9_]*\.json\(\)\s*$",
                line,
            )
        ):
            indent = re.match(r"^(\s*)", line).group(1)
            output.append(indent + "_redsight_stage10_commit(data)")
            inserted = True
    if not inserted:
        raise RuntimeError(
            "Could not locate 'data = response.json()' in _send_to_api."
        )
    method = "\n".join(output)
    if method_match.group(0).endswith("\n"):
        method += "\n"

command_source = (
    command_source[:method_match.start()]
    + method
    + command_source[method_match.end():]
)

ast.parse(command_source, filename=str(COMMAND_CENTER))

launcher = read(LAUNCHER)

launcher = re.sub(
    (
        r"(?m)^from app\.ui\.action_palette"
        r"(?:_stage9|_stage91|_stage10)? "
        r"import install_action_hooks, attach_action_palette\s*$\n?"
    ),
    "",
    launcher,
)

launcher = re.sub(
    r"(?m)^\s*install_action_hooks\(CommandCenterMainWindow\)\s*$\n?",
    "",
    launcher,
)

launcher = re.sub(
    r"(?m)^\s*attach_action_palette\(.*?\)\s*$\n?",
    "",
    launcher,
)

if not re.search(r"(?m)^from pathlib import Path\s*$", launcher):
    future = re.search(r"(?m)^from __future__ import .+$", launcher)
    if future:
        launcher = (
            launcher[:future.end()]
            + "\nfrom pathlib import Path"
            + launcher[future.end():]
        )
    else:
        launcher = "from pathlib import Path\n" + launcher

command_import = re.search(
    (
        r"(?m)^from app\.ui\.command_center "
        r"import CommandCenterMainWindow\s*$"
    ),
    launcher,
)
if not command_import:
    raise RuntimeError("CommandCenterMainWindow import not found in launcher.")

integration = (
    "\nfrom app.ui.action_palette_stage10 "
    "import install_action_hooks, attach_action_palette\n"
    "install_action_hooks(CommandCenterMainWindow)"
)

launcher = (
    launcher[:command_import.end()]
    + integration
    + launcher[command_import.end():]
)

window_match = re.search(
    r"(?m)^([ \t]*)window\s*=\s*CommandCenterMainWindow\(\)\s*$",
    launcher,
)
if not window_match:
    raise RuntimeError("CommandCenterMainWindow() construction not found.")

indent = window_match.group(1)
attach_line = (
    indent
    + "attach_action_palette(window, Path(__file__).resolve().parent)"
)

launcher = (
    launcher[:window_match.end()]
    + "\n"
    + attach_line
    + launcher[window_match.end():]
)

ast.parse(launcher, filename=str(LAUNCHER))

atomic_write(GATEWAY10, GATEWAY_SOURCE)
atomic_write(PALETTE10, PALETTE_SOURCE)
atomic_write(COMMAND_CENTER, command_source)
atomic_write(LAUNCHER, launcher)

startup_dir = (
    Path(os.environ["APPDATA"])
    / "Microsoft"
    / "Windows"
    / "Start Menu"
    / "Programs"
    / "Startup"
)
startup_dir.mkdir(parents=True, exist_ok=True)

pythonw = ROOT / ".venv-actions" / "Scripts" / "pythonw.exe"
python = ROOT / ".venv-actions" / "Scripts" / "python.exe"
gateway_python = pythonw if pythonw.exists() else python

startup_text = (
    "@echo off\n"
    'cd /d "C:\\Users\\walim\\RedSight"\n'
    'start "" /min "'
    + str(gateway_python)
    + '" -m uvicorn redsight_actions.gateway_stage10:app '
    + "--host 127.0.0.1 --port 8765 --log-level warning\n"
)

atomic_write(
    startup_dir / "RedSight-Action-Gateway.cmd",
    startup_text,
)

manual_text = (
    "@echo off\n"
    'cd /d "C:\\Users\\walim\\RedSight"\n'
    '"'
    + str(python)
    + '" -m uvicorn redsight_actions.gateway_stage10:app '
    + "--host 127.0.0.1 --port 8765 --log-level info\n"
)

atomic_write(
    ROOT / "START-REDSIGHT-ACTIONS.cmd",
    manual_text,
)

print("STAGE10_SOURCE_INSTALL=PASS")
print("BACKUP=" + str(BACKUP))
print("DATABASE=" + str(Path(os.environ["LOCALAPPDATA"]) / "RedSight" / "memory" / "conversations.sqlite"))
